import csv,json,collections
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'Reports/GeometryAudit'
d=json.loads((OUT/'NativeInventory.json').read_text())
rows=d['rows']; catalog=d['catalog']
# Keep grouping reproducible and tied to asset IDs/hierarchy; preserve raw native categories.
for r in rows:
 if r['category']=='Playable machinery':r['owner']=r['path'].split('/')[0]
 elif not r['owner']:r['owner']=r['path']
 if r['category']=='Other catalog scenery' and 'vehicle' in r['assetId']:r['category']='Parked vehicles'

def n(x):return f'{x:,}'
def total(rs,key):return sum(r[key] for r in rs)
def table(headers,rs):return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+''.join('| '+' | '.join(str(x).replace('|',' / ') for x in row)+' |\n' for row in rs)
def csvout(name,data):
 if not data:return
 with (OUT/name).open('w',newline='',encoding='utf-8-sig') as f:
  w=csv.DictWriter(f,fieldnames=list(data[0]));w.writeheader();w.writerows(data)

csvout('SceneRenderers.csv',rows);csvout('CatalogAssets.csv',catalog)
groups=collections.defaultdict(list)
for r in rows:groups[r['category']].append(r)
sums=[]
for cat,rs in groups.items():
 sums.append(dict(category=cat,vertices=total(rs,'vertices'),triangles=total(rs,'triangles'),renderers=len(rs),materialSlots=total(rs,'slots'),uniqueMaterials=len(set(m for r in rs for m in r['materials'])),shadowRenderers=sum(r['castsShadows'] for r in rs),activeEnabledTriangles=sum(r['triangles'] for r in rs if r['active'] and r['enabled'])))
sums.sort(key=lambda r:r['triangles'],reverse=True);csvout('SceneCategories.csv',sums)
forest=[a for a in catalog if a['id'].startswith('alpine-tree-')];forest.sort(key=lambda a:a['id'])
forestrows=[r for r in rows if r['assetId'].startswith('alpine-tree-')]
forest_instances=collections.defaultdict(list)
for r in forestrows:forest_instances[r['owner']].append(r)
csvout('TreesByPlacement.csv',[dict(placementId=owner,assetId=rs[0]['assetId'],vertices=total(rs,'vertices'),triangles=total(rs,'triangles'),renderers=len(rs),materialSlots=total(rs,'slots')) for owner,rs in sorted(forest_instances.items())])
assert len(forest)==26
assert sum(a['placements'] for a in forest)==len(set(r['owner'] for r in forestrows))
assert sum(a['placements']*a['triangles'] for a in forest)==total(forestrows,'triangles')
assert sum(a['placements']*a['vertices'] for a in forest)==total(forestrows,'vertices')
for a in forest:
 a['sceneVertices']=a['vertices']*a['placements'];a['sceneTriangles']=a['triangles']*a['placements']
csvout('TreesByVariant.csv',forest)
trees=[a for a in forest if int(a['id'][-2:])<=20];wood=[a for a in forest if int(a['id'][-2:])>20]
unique={r['meshId']:r for r in rows}
text='# Pinefall asset geometry audit\n\nMeasured from the **saved scene**, 6 November 2026, using Unity '+d['unity']+' / '+d['target']+'. Read-only preview-scene inventory; no gameplay, geometry, placement, snow, save or material changes. Active Editor scene and dirty state retained.\n\n'
text+='## Counting method and limits\n\nVertices are Unity `Mesh.vertexCount`, including normal/UV/color splits, not welded Blender control points. Triangles are triangle-topology index counts divided by three. Scene totals count every placed mesh renderer instance once, including inactive/disabled authored meshes; shared assets repeat for each placement. Unique-mesh totals count each GUID/local ID once and describe mesh reuse, not total RAM or GPU memory. Material slots are submission candidates, **not measured draw calls**. Catalog prefab totals include inactive authored mesh children; scene-only caption/rear-panel additions can make placed geometry differ from the catalog.\n\n'
text+='Terrain, particles, dynamic world lettering and Canvas UI are separated below. No camera-frustum/occlusion/shadow-pass multiplication is applied; these are **whole-scene content totals, not rendered-frame counts, FPS or GPU/CPU milliseconds**. Actual Play snow shape, particle counts, vehicle visibility and camera location change the cost.\n\n'
text+='## Whole-scene mesh inventory\n\n'
text+=table(['Asset type','Vertices across placements','Triangles across placements','Renderers','Material slots','Shadow-casting renderers'],[[s['category'],n(s['vertices']),n(s['triangles']),n(s['renderers']),n(s['materialSlots']),n(s['shadowRenderers'])] for s in sums])
text+='\nTotal: **'+n(total(rows,'vertices'))+' vertices / '+n(total(rows,'triangles'))+' triangles / '+n(len(rows))+' mesh renderers**. Distinct mesh assets: '+n(len(unique))+'; their combined geometry is '+n(total(unique.values(),'vertices'))+' vertices / '+n(total(unique.values(),'triangles'))+' triangles. Static saved active+enabled mesh inventory: '+n(sum(r['triangles'] for r in rows if r['active'] and r['enabled']))+' triangles, still before camera culling.\n\n'
text+='## Forest: every tree and wood variant\n\nAll 26 variants use LOD3. **'+n(sum(a['placements'] for a in forest))+' placements; '+n(total(forestrows,'vertices'))+' vertices; '+n(total(forestrows,'triangles'))+' triangles; '+n(len(forestrows))+' renderers.**\n\n'
text+=table(['Part','Placements','Vertices in scene','Triangles in scene'],[[label,n(sum(a['placements'] for a in arr)),n(sum(a['sceneVertices'] for a in arr)),n(sum(a['sceneTriangles'] for a in arr))] for label,arr in [('Trees/snags (01–20)',trees),('Stumps/logs (21–26)',wood)]])
text+='\n'+table(['Variant','Name','Vertices each','Triangles each','Placed','Scene triangles'],[[a['id'][-2:],a['name'],n(a['vertices']),n(a['triangles']),a['placements'],n(a['sceneTriangles'])] for a in forest])
text+='\nForest is '+f"{100*total(forestrows,'triangles')/total(rows,'triangles'):.1f}%"+' of inventoried mesh triangles (Terrain/particles/UI excluded). Catalog sum for one of each of the 26 variants: '+n(sum(a['vertices'] for a in forest))+' vertices / '+n(sum(a['triangles'] for a in forest))+' triangles. Forest geometry reconciles exactly between per-variant multiplication and measured placed renderers.\n\n'
text+='## Per-asset counts for other placed catalog variants\n\nCounts below describe one reusable prefab, not multiplied instances. Scene-only edits remain in the category totals above. Complete unplaced/prototype catalog entries are in CatalogAssets.csv.\n\n'
placed=sorted([a for a in catalog if a['placements'] and not a['id'].startswith('alpine-tree-')],key=lambda a:(a['kind'],a['id']))
text+=table(['Asset ID / name','Vertices each','Triangles each','Renderers each','Material slots each','Placements'],[[a['id']+' / '+a['name'],n(a['vertices']),n(a['triangles']),a['renderers'],a['slots'],a['placements']] for a in placed])
text+='\n## Machinery as actually saved in the scene\n\n'
machines=collections.defaultdict(list)
for r in rows:
 if r['category']=='Playable machinery':machines[r['owner']].append(r)
text+=table(['Machine','Vertices','Triangles','Renderers','Slots','Distinct materials'],[[k,n(total(rs,'vertices')),n(total(rs,'triangles')),len(rs),total(rs,'slots'),len(set(m for r in rs for m in r['materials']))] for k,rs in machines.items()])
text+='\nIncludes saved inactive carried-snow/lamp mesh children; excludes emitted particle instances.\n\n## Separate costs and exclusions\n\n'
for t in d['terrains']:
 text+=f"- Terrain `{t['name']}`: {t['resolution']} × {t['resolution']} height samples; un-LOD full-grid reference {n(t['fullGridVertices'])} vertices / {n(t['fullGridTriangles'])} triangles. **Not an actual terrain draw count**: adaptive tessellation/culling depends on camera and pixel error ({t['pixelError']}). Instanced terrain: {t['instanced']}.\n"
text+=f"- {d['unmeasuredRenderers']} renderers without a saved mesh were excluded (including engine-generated world text/sprites); UI Canvas geometry is also outside this mesh audit.\n"
text+=f"- {len(d['particles'])} authored particle systems are listed in NativeInventory.json; actual particle geometry is not multiplied into scene totals.\n"
for p in d['particles']:
 if p['meshTriangles']:text+=f"- Mesh particles `{p['path'].split('/')[-1]}`: {p['meshVertices']} vertices / {p['meshTriangles']} triangles **per puff**, capacity {p['maxParticles']}; capacity ceiling {n(p['meshTriangles']*p['maxParticles'])} triangles per system, not an observed simultaneous count.\n"
text+=f"- {d['colliders']} saved colliders; {d['enabledColliders']} active+enabled. {d['lights']} saved Light components; {d['enabledLights']} active+enabled in Editor state, before runtime gates. Collision, light/shadow, texture, shader, transparent fill-rate, snow-update, UI and save costs cannot be inferred from triangle counts.\n"
if d['culling']:
 count=collections.Counter(c['distance'] for c in d['culling']);text+='- Existing distance-culling components: '+', '.join(f'{v} at {k:g} m' for k,v in sorted(count.items()))+'. DistanceVisibility checks selected-machine distance every 0.7 s; this does not guarantee every tree inside the radius is visible to the camera.\n'
assessment={'Interactive snow': 'Largest single mesh category; profile visible chunks, mesh/collider rebuilds and shadows before reducing simulation/visual resolution.', 'Homes': '40 homes, 160 renderers. Per-model geometry is reasonable; investigate rigid-part/material consolidation while keeping removable snow and windows.', 'Trees and wood (LOD3)': 'Already lowest LOD3. Keep existing 230 m distance culling; investigate snowy canopy geometry only if the forest is a measured bottleneck.', 'Sign boards': '102 renderers for 18,050 triangles, including inactive original artwork. Consider merging rigid same-material pieces per board, preserving edited captions and rear panels.', 'Street lights': '75 renderers and three shared materials. Consider per-fixture combining; preserve lens/snow control and avoid enabling optional real-time lights across the town.', 'Playable machinery': '43 renderers and 67 material slots. Investigate slot consolidation before triangle decimation; preserve wheels, blade/bucket articulation, snow load and light switching.', 'Parked vehicles': 'Five vehicles, 15 renderers and 13,344 triangles. Low priority for geometry reduction.', 'Clouds': '40 opaque renderers, 13,280 triangles, no shadow casters. Keep geometry; investigate compatible repetition batching only if submissions are a bottleneck.', 'Mountains': '12 mountains total only 10,088 triangles. Keep nearby geometry; panorama can supply beyond-geometry scenery. Low priority for decimation.', 'Facilities': 'Garage/fuel station/disposal yard total 7,844 triangles. Keep geometry; combine only rigid same-material pieces if measured submission cost warrants it.', 'Lot foundations and fences': 'Many renderers for very few triangles. Candidate for small per-lot batching experiments; preserve separate collision and useful culling boundaries.', 'Snowmen': 'Three models, six renderers and 3,000 triangles. No geometry reduction justified by these counts.', 'Traction ramp': 'One ramp, two renderers and 2,668 triangles. Keep its low-cost smooth collision deck; low priority for decimation.', 'Roads, curbs and markings': '25 renderers and 2,532 triangles. Modest geometry; retain combined paint and current accesses.', 'Other authored scenery': 'Only eight renderers and 96 triangles; negligible geometry.'}
text+='## Assessment by asset type\n\n'+table(['Type','Suggested action'],[[v['category'],assessment[v['category']]] for v in sums])+'\n'
text+='\n## Performance suggestions, in priority order\n\n1. **Measure the Android build on Galaxy A07 before reducing assets.** Target is 30 FPS / 33.3 ms per frame. Compare CPU, render-thread and GPU times, Rendering Profiler batches/SetPass, snow updates and GC in town, dense forest, depot and maximum snow pushing. This audit measures no frame-time savings; triangle percentages are not performance percentages.\n2. **Interactive snow and Terrain first if geometry/updates dominate.** The category totals reveal how much mesh snow contributes; profile dirty-chunk rebuilds/colliders, Terrain pixel error and visible area. Consider smaller visual detail only after preserving the snow-volume ledger and blade/tyre interaction. Terrain’s full-grid reference must not be added as if it were rendered every frame.\n3. **Batch rigid foundations/fences in small per-lot groups if CPU submission dominates.** They contribute only 3,840 triangles but 320 renderers. Preserve individual collision boxes and useful culling boundaries. Material sharing/SRP batching may already make some submissions cheap, so verify the device/Frame Debugger before choosing a rewrite.\n4. **Forest: keep LOD3 and existing distance culling.** No broad decimation is justified solely by the current totals. Snowy Open Alpine Larch (14) is the heaviest variant at 1,315 triangles; compare its screen footprint and snow-cap topology before simplifying it. Test a lower density of the heaviest snowy variants or culling changes only if forest views are a measured bottleneck. Do not reintroduce the unused higher LODs.\n5. **Repeated trees/homes/street lights: investigate submission and shadows.** Shared mesh/material repetitions are candidates for compatible instancing or modest spatial batching. Verify shader/URP/SRP Batcher compatibility and actual Frame Debugger results; a checkbox is not proof of batching. Avoid combining the whole forest into one giant mesh, which weakens culling. Distant tree/street-light shadow distance or casting can be a better experiment than removing triangles, subject to visual approval.\n6. **Homes and machinery: inspect renderer/material fragmentation.** Current one-box home collision policy already reduces physics complexity; it does not reduce render work. Combine only rigid parts with identical materials in Editor, keeping snow caps, wheels, blades, doors and glow independently controllable. Check street-light meshes and home fences as repeated submissions, rather than removing their visible details first.\n7. **Mountains and facilities: retain current low-poly geometry unless profiling says otherwise.** A skybox can provide scenery beyond the modeled ring, but triangle counts alone do not justify deleting the nearby mountains. The one-off ramp and service buildings are low-priority decimation targets.\n8. **Transparency and lighting require a different budget.** Exhaust puffs, glows and bloom can cost fill-rate despite tiny triangle counts. Keep optional street lights gated, keep vehicle beam/shadow counts controlled, and measure overdraw with the camera close to smoke. No geometry-only estimate can price these effects.\n\nNo optimization has been applied. Suggested experiments require before/after device capture; there is no defensible FPS improvement estimate from this inventory alone.\n\n'
text+='## Evidence and repeat workflow\n\n- `NativeInventory.json`: native saved-mesh measurements and render/culling/terrain context.\n- `SceneRenderers.csv`: every measured renderer, owner, mesh, vertices, triangles, materials, active/enabled and shadow flags.\n- `SceneCategories.csv`: category totals.\n- `TreesByVariant.csv`: all 26 tree/wood variants, placements and totals.\n- `TreesByPlacement.csv`: one row for each placed tree/log/stump.\n- `CatalogAssets.csv`: all catalog prefab variants, including unused entries.\n- `Validation.txt`: read-only state preservation result.\n\nRepeat: **Snowglow > Audit > Saved scene geometry inventory (read only)**, then `python Tools/AssetIntake/report_geometry_audit.py`. Audit always measures the saved Pinefall scene, not unsaved Editor edits.\n\n'
text+='Unity references: [optimizing many objects](https://docs.unity.com/en-us/engine/6000.3/manual/analysis/graphics-performance-profiling/reduce-draw-calls), [GPU instancing](https://docs.unity.com/en-us/engine/6000.0/manual/analysis/graphics-performance-profiling/reduce-draw-calls/gpuinstancing/gpuinstancing), [profiling on target devices](https://activation.unity3d.com/how-to/best-practices-for-profiling-game-performance).\n'
(OUT/'AssetGeometryAudit.md').write_text(text,encoding='utf-8')
print(json.dumps({'sceneVertices':total(rows,'vertices'),'sceneTriangles':total(rows,'triangles'),'forestVertices':total(forestrows,'vertices'),'forestTriangles':total(forestrows,'triangles'),'categories':sums},indent=2))

